const std = @import("std");

pub fn main() !void {
    const json = "{\"name\":\"Zig\",\"year\":2024}";
    var i: usize = 0;

    while (i < json.len) {
        switch (json[i]) {
            '{', '}', ',', ':' => {
                std.debug.print("{c} ", .{json[i]});
                i += 1;
            },
            '"' => {
                i += 1;
                while (i < json.len and json[i] != '"') { i += 1; }
                if (i < json.len) i += 1;
            },
            else => |_| i += 1,
        }
    }
    std.debug.print("\n", .{});
}

